}

.action-btn-clean:hover {
  background: var(--primary-color);
  color: white;
  transform: translateY(-3px);
  box-shadow: 0 8px 15px rgba(93, 156, 236, 0.3);
}

.action-btn-clean::before {
  content: '';
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent-color);
  margin-right: 12px;
  transition: all 0.3s ease;
}

.action-btn-clean.active {
  background: var(--primary-color);
  color: white;
  padding-left: 22px;
}

.action-btn-clean.active::before {
  background: white;
  transform: scale(1.2);
}

/* 页脚（新增猫咪脚印） */
.clean-footer {
  text-align: center;
  padding: 15px 0 0;
  margin-top: 20px;
  font-size: 0.8em;
  color: #888;
  border-top: 1px solid rgba(0, 0, 0, 0.05);
  position: relative;
}

.clean-footer::before {
  content: '🐾🐾🐾';
  position: absolute;
  top: -15px;
  left: 0;
  right: 0;
  text-align: center;
