  const mpMatch = data.match(/\[MP:(\d+(?:\.\d+)?)\/(\d+(?:\.\d+)?)\]/);
  if (mpMatch) {
    battleData.player.mp = parseFloat(mpMatch[1]);
    battleData.player.maxMp = parseFloat(mpMatch[2]);
