            attack: parseFloat(match[2]),
            hitRate: parseFloat(match[3]),
            critRate: parseFloat(match[4]),
            attacksPerTurn: parseInt(match[5]),
            targetsPerAttack: match[6] ? parseInt(match[6]) : 1, 
          });
        });

        if (patternMatch) {
          enemy.attackPattern = patternMatch[1].split(',');
        } else if (enemy.skills.length > 0) {

          enemy.attackPattern = enemy.skills.map(skill => skill.name);
        }
        battleData.enemies.push(enemy);
      }
    });
  }
  return battleData;
}

