            );
            const expResult = calculateTeamExperience(battleState.player, battleState.teammates, defeatedEnemies);
            expInfo = `，{{user}}获得${expResult.playerExp}经验值`;
            if (expResult.teammateResults && expResult.teammateResults.length > 0) {
