  enemy.stacks.trauma = (enemy.stacks.trauma || 0) + stacks;
  logBattleAction(
    `创伤叠加！${enemy.name} 获得 ${stacks} 层创伤效果（总计 ${enemy.stacks.trauma} 层），每层每回合造成 ${damage} 点伤害！`,
  );
}
function handleCorrosionStack(params, enemy) {
