      function logBattleAction(message) {

        let logEntry;
        if (memoryManager.logEntryPool.length > 0) {
          logEntry = memoryManager.logEntryPool.pop();
          logEntry.textContent = message;
        } else {
          logEntry = document.createElement('div');
          logEntry.className = 'log-entry';
          logEntry.textContent = message;
        }

        combatLog.appendChild(logEntry);
        combatLog.scrollTop = combatLog.scrollHeight;

        const COMBAT_LOG_MAX_LINES = 10;
        while (combatLog.children.length > COMBAT_LOG_MAX_LINES) {
          const removedEntry = combatLog.removeChild(combatLog.firstChild);

          if (memoryManager.logEntryPool.length < 20) {
            removedEntry.textContent = '';
            memoryManager.logEntryPool.push(removedEntry);
          }
        }

        if (battleState && battleState.fullCombatLog) {
          battleState.fullCombatLog.push(message);

          if (battleState.fullCombatLog.length > 200) {
            battleState.fullCombatLog = battleState.fullCombatLog.slice(-100); 
          }
        }
      }

