                      <p>HP变为0</p>
                  `;
        }

        const battleStats = collectBattleStatistics();

        resultModal.style.display = 'flex';

        closeResultBtn.removeEventListener('click', closeResultHandler);
        sendResultBtn.removeEventListener('click', sendResultHandler);

        closeResultBtn.addEventListener('click', function () {
