  userEntity.mp = Math.min(userEntity.mp + item.value, userEntity.maxMp);
  const actualRestore = userEntity.mp - oldMp;
  logBattleAction(`${isPlayer ? '' : userEntity.name + ' '}恢复了 ${actualRestore} 点灵力值！`);

