      };

      const enchantmentEffects = {
        B1: percent => `气血汲取：攻击造成伤害的${percent}%转化为气血值`,
        B2: (duration, value) => `减益-命中：攻击命中时，目标在接下来${duration}个回合内命中率降低${value}%`,
        B3: (duration, value) => `增益-会心：会心后，你在接下来${duration}个回合内会心率提高${value}%`,
        B4: duration => `触发-定身：会心时定身敌修${duration}回合`,
        B5: (duration, damage) => `伤害-持续：${duration}回合内每回合造成${damage}点持续伤害`,
        B6: (chance, duration) => `几率-定身：${chance}%几率定身目标${duration}回合`,
