      function calculateActionOrder() {

        battleState.actionOrder = [];
        battleState.currentActionIndex = 0;
        battleState.actionsThisRound = {};

        const allParticipants = [];

        allParticipants.push({
          type: 'player',
          id: 'player',
          name: battleState.player.name || 'User',
          speed: battleState.player.speed,
          entity: battleState.player,
        });

        battleState.teammates.forEach(teammate => {
          allParticipants.push({
            type: 'teammate',
            id: teammate.id,
            name: teammate.name,
            speed: teammate.speed,
            entity: teammate,
          });
        });

        battleState.enemies.forEach(enemy => {
          allParticipants.push({
            type: 'enemy',
            id: enemy.id,
            name: enemy.name,
            speed: enemy.speed,
            entity: enemy,
          });
        });

        const minSpeed = Math.min(...allParticipants.map(p => p.speed));

        const actionPool = [];

        allParticipants.forEach(participant => {

          actionPool.push({
            type: participant.type,
            id: participant.id,
            name: participant.name,
            entity: participant.entity,
            speed: participant.speed,
            actionNumber: 1,
          });

          let extraActionCount = 1;
          let currentSpeed = participant.speed;
          while (currentSpeed >= minSpeed * 2) {

            currentSpeed = Math.floor(currentSpeed / 2);
            extraActionCount++;
            actionPool.push({
              type: participant.type,
              id: participant.id,
              name: participant.name,
              entity: participant.entity,
              speed: currentSpeed,
              actionNumber: extraActionCount,
            });
          }
        });

        actionPool.sort((a, b) => b.speed - a.speed);

        battleState.actionOrder = actionPool;

        allParticipants.forEach(participant => {
          battleState.actionsThisRound[`${participant.type}-${participant.id}`] = 0;
        });

        let actionOrderText = '行动顺序: ';
        battleState.actionOrder.forEach((action, index) => {
          actionOrderText += `${index + 1}.${action.name}`;
          if (index < battleState.actionOrder.length - 1) {
            actionOrderText += ' → ';
          }
        });
        logBattleAction(actionOrderText);
        return battleState.actionOrder;
      }

      function startBattle() {
        const data = statusDataSource.textContent;
        battleData = parseStatusData(data);
        const selectedEnemyElements = document.querySelectorAll('#pilots-container .enemy-item.selected');
        const selectedEnemyIndices = Array.from(selectedEnemyElements).map(el =>
          parseInt(el.getAttribute('data-enemy-index')),
        );
        const selectedEnemies = battleData.enemies.filter((enemy, index) => selectedEnemyIndices.includes(index));
        if (selectedEnemies.length === 0) {
          alert('请至少选择一个敌修进行战斗！');
          return;
        }

        const selectedTeammates = battleState.selectedTeammates || [];
        battleState.isActive = true;
        battleState.round = 1;

        battleState.currentItemUsed = false;
        battleState.playerBuffs = [];
        battleState.player = JSON.parse(JSON.stringify(battleData.player));
        battleState.teammates = JSON.parse(JSON.stringify(selectedTeammates)); 
        battleState.currentTeammate = null; 
        battleState.enemies = JSON.parse(JSON.stringify(selectedEnemies));
        battleState.initialEnemies = JSON.parse(JSON.stringify(selectedEnemies));
        battleState.selectedEnemies = [];
