    attackBtn.disabled = true;
  }
  const nextRoundBtn = document.getElementById('next-round-btn');
  if (nextRoundBtn) {
    nextRoundBtn.disabled = true;
  }
  const midActionBtn = document.getElementById('mid-action-btn');
  if (midActionBtn) {
